package android.util; public class MathUtils { public static float sq(float v) { return v*v; } public static float exp(float v) { return (float)Math.exp(v); } public static float log(float v) { return (float)Math.log(v); } public static float sqrt(float v) { return (float)Math.sqrt(v); } public static float constrain(float v, float lo, float hi) { return Math.max(lo,Math.min(hi,v)); } }
